	return Definition{Type: "function", Name: "manage_automation", Description: AutomationV2AuthoringInstructions + " This tool only reads V2 review/context, progress with explicit display timezone, or bounded accepted records in the current workspace. Mutations use the plan review workflow; V1 save/approve/enable/run are retired.", Parameters: map[string]any{"type": "object", "additionalProperties": false, "required": []string{"action"}, "properties": map[string]any{"action": map[string]any{"type": "string", "enum": []string{"review", "context", "list", "progress"}}, "cursor": map[string]any{"type": "string"}, "timezone": map[string]any{"type": "string"}, "limit": map[string]any{"type": "integer", "minimum": 1, "maximum": 50}}}}
